<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue';
import {invoke,assetsContextRevision} from './ports/client.mjs';
import {assetConfirm} from './ports/dialogs.mjs';
import {useI18n} from './ports/i18n';
import {cloneAssetProfile,editableSettings,profileInput,importCollectionFile} from './configuration.mjs';
const emit=defineEmits<{updated:[]}>();const {tr}=useI18n();
const profiles=ref<any[]>([]),draft=ref<any>(),unsupported=ref<string[]>([]),error=ref(''),status=ref(''),busy=ref(false),copy=ref(false);
let alive=true,generation=0;
const fields=[['collectionMode','采集模式','Collection mode','text'],['fofaProfile','来源账户类型','Provider plan','text'],['pageSize','每页条数','Page size','number'],['maxPages','最多页数（0 不设本项上限）','Maximum pages (0: no limit here)','number'],['maxDerivedDomains','派生域名上限','Derived domain limit','number'],['interval','请求间隔（秒）','Request interval (seconds)','number'],['collectionTimeout','采集超时（秒）','Collection timeout (seconds)','number'],['workers','探测工作数','Probe workers','number'],['probeTimeout','单次探测超时（秒）','Probe timeout (seconds)','number'],['probeTotalTimeout','单资产探测总超时（秒）','Total probe timeout (seconds)','number'],['probeRetries','探测重试次数','Probe retries','number'],['priorityRate','优先请求速率','Priority rate','number'],['otherRate','其他请求速率','Other rate','number'],['perHostInterval','同主机间隔（秒）','Per-host interval (seconds)','number'],['maxBodyBytes','响应正文上限（字节）','Response body limit (bytes)','number'],['contentThreshold','内容规则阈值','Content threshold','number'],['proxyUrl','代理 URL','Proxy URL','text'],['noProxy','绕过代理','No proxy','text']];
const flags=[['runProbe','采集后实际探测','Probe after collection'],['runRefine','执行本地精炼','Run local refinement'],['fullHistory','请求完整历史','Request full history'],['enableCidr24','派生 /24 网段','Derive /24 networks'],['includeWeakFingerprints','包含弱指纹','Include weak fingerprints'],['includeOther','包含其他协议','Include other protocols'],['includeWeak','包含弱结果','Include weak results'],['allowPrivate','允许私网目标','Allow private targets'],['strictTls','严格 TLS','Strict TLS'],['schemeFallback','尝试备用协议','Scheme fallback'],['replaceDefaultContentRules','替换内置内容规则','Replace built-in content rules']];
async function load(){const current=++generation;busy.value=true;error.value='';try{const rows=await invoke('list_config_profiles');if(!alive||current!==generation)return;if(!Array.isArray(rows))throw Error('assets_profiles_invalid');profiles.value=rows;}catch(e){if(alive&&current===generation)error.value=String(e);}finally{if(alive&&current===generation)busy.value=false;}}
function edit(profile:any,clone=false){const prepared=editableSettings(profile.settings);unsupported.value=prepared.unsupported;draft.value={...cloneAssetProfile(profile),settings:prepared.settings,name:clone?`${profile.name} ${tr('副本','copy')}`:profile.name};copy.value=clone;if(clone){draft.value.isDefault=false;draft.value.settings.collectionConfigurationId='';draft.value.settings.configPath='';}status.value='';error.value='';}
async function save(){if(!draft.value||busy.value||unsupported.value.length)return;const current=++generation;busy.value=true;error.value='';try{const input=profileInput(draft.value,{copy:copy.value});const id=await invoke('save_config_profile',{input});if(!alive||current!==generation)return;const rows=await invoke('list_config_profiles');if(!alive||current!==generation)return;if(!Array.isArray(rows)||!rows.some(row=>row.id===id))throw Error('assets_profile_saved_readback_unconfirmed');profiles.value=rows;edit(rows.find(row=>row.id===id));status.value=tr('配置已保存并读取核对；没有测试账户或启动任务。','Profile saved and read back. No account test or task was started.');emit('updated');}catch(e){if(alive&&current===generation)error.value=String(e);}finally{if(alive&&current===generation)busy.value=false;}}
async function remove(profile:any){if(busy.value||profile.isDefault)return;const scope=assetsContextRevision();if(!await assetConfirm(tr(`删除配置「${profile.name}」？历史任务仍保留。`,`Delete profile ${profile.name}? Historical jobs are retained.`))||!alive||scope!==assetsContextRevision())return;busy.value=true;error.value='';try{await invoke('delete_config_profile',{profileId:profile.id});draft.value=undefined;await load();emit('updated');}catch(e){error.value=String(e);}finally{busy.value=false;}}
async function fileChanged(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];input.value='';if(!file||!draft.value||busy.value)return;const scope=assetsContextRevision(),current=++generation;busy.value=true;error.value='';try{const receipt=await importCollectionFile(file,invoke,()=>alive&&current===generation&&scope===assetsContextRevision());draft.value.settings.collectionConfigurationId=receipt.configurationId;draft.value.settings.configPath='';draft.value.settings.fofaKey='';status.value=tr('已导入应用私有配置，尚未保存到本档案。内容与密钥不会回读到页面。','Private configuration imported; save this profile to bind it. File contents and credentials are not returned to this page.');}catch(e){if(alive&&current===generation)error.value=String(e);}finally{if(alive&&current===generation)busy.value=false;}}
function flagChanged(key:string,event:Event){if(!draft.value)return;const value=(event.target as HTMLSelectElement).value;if(value==='unset')delete draft.value.settings[key];else draft.value.settings[key]=value==='true';}
onMounted(load);onUnmounted(()=>{alive=false;generation++;if(draft.value?.settings)draft.value.settings.fofaKey='';});
</script>
<template><section class="panel configuration-profiles"><header class="panel-heading"><h2>{{tr('应用执行配置','Application execution profiles')}}</h2><button class="button secondary" :disabled="busy" @click="load">{{tr('刷新','Refresh')}}</button></header><p>{{tr('这些配置影响此资产应用的所有项目。保存不会启动采集或测试付费账户；采集与探测仍须另行明确执行。','These profiles are shared by all projects in this Assets app. Saving does not start collection or test an account; collection and probing require a separate explicit action.')}}</p><p v-if="error" role="alert" class="app-notice error">{{error}}</p><p v-if="status" role="status" class="app-notice">{{status}}</p>
<div class="profile-list"><article v-for="profile in profiles" :key="profile.id"><strong>{{profile.name}}</strong> {{profile.isDefault?tr('默认','Default'):''}}<span>{{profile.settings.fofaKeyConfigured?tr('来源密钥已配置','Provider credential configured'):tr('来源密钥未配置','Provider credential not configured')}}</span><button class="button secondary" :disabled="busy" @click="edit(profile)">{{tr('编辑配置','Edit profile')}}</button><button class="button ghost" :disabled="busy" @click="edit(profile,true)">{{tr('复制为新配置','Copy as new profile')}}</button><button class="button ghost" :disabled="busy||profile.isDefault" @click="remove(profile)">{{tr('删除','Delete')}}</button></article></div>
<div v-if="draft" class="profile-editor"><h3>{{copy?tr('新配置副本','New profile copy'):tr('编辑已保存配置','Edit saved profile')}}</h3><p v-if="unsupported.length" role="alert" class="app-notice error">{{tr('发现本版本尚不认识的设置，已保留并阻止保存，以免覆盖。','Unrecognized settings were retained. Saving is blocked to prevent data loss.')}} {{unsupported.join(', ')}}</p>
<div class="profile-fields"><label><span>{{tr('配置名称','Profile name')}}</span><input v-model="draft.name" :disabled="busy"></label><label><span>{{tr('说明','Description')}}</span><input v-model="draft.description" :disabled="busy"></label><label class="checkbox-row"><input v-model="draft.isDefault" type="checkbox" :disabled="busy">{{tr('作为默认执行配置','Use as the default execution profile')}}</label><label><span>{{tr('新的来源密钥（留空保留旧密钥）','New provider key (blank retains existing key)')}}</span><input v-model="draft.settings.fofaKey" type="password" autocomplete="new-password" :disabled="busy"></label><label><span>{{tr('导入来源配置文件（最多 64 KiB）','Import provider configuration (up to 64 KiB)')}}</span><input type="file" :disabled="busy" @change="fileChanged"></label><p v-if="draft.settings.collectionConfigurationId">{{tr('已选择私有导入配置','Private imported configuration selected')}} · {{draft.settings.collectionConfigurationId}}</p><label v-for="field in fields" :key="field[0]"><span>{{tr(field[1],field[2])}}</span><input v-if="field[3]==='number'" v-model.number="draft.settings[field[0]]" type="number" :disabled="busy"><input v-else v-model="draft.settings[field[0]]" :disabled="busy"></label></div>
<div class="profile-fields"><label v-for="flag in flags" :key="flag[0]"><span>{{tr(flag[1],flag[2])}}</span><select :value="typeof draft.settings[flag[0]]==='boolean'?String(draft.settings[flag[0]]):'unset'" :disabled="busy" @change="flagChanged(flag[0],$event)"><option value="unset">{{tr('未显式设置（保留执行器默认）','Not explicitly set (retain engine default)')}}</option><option value="true">{{tr('启用','Enabled')}}</option><option value="false">{{tr('停用','Disabled')}}</option></select></label></div><p>{{tr('填写新的来源密钥会解绑当前导入文件；留空不会删除现有密钥。模型与其他现有设置原样保留；保存不登录模型、不授权、不启动扫描。复制配置不会自动继承私有导入文件。','A newly entered provider key replaces the imported file binding; blank retains an existing key. Existing model and other settings are retained. Saving does not log in, grant permissions or start a scan. Copies do not inherit a private imported file automatically.')}}</p><button class="button primary" :disabled="busy||unsupported.length>0||!draft.name.trim()" @click="save">{{tr('保存配置','Save profile')}}</button><button class="button ghost" :disabled="busy" @click="draft=undefined">{{tr('关闭编辑器','Close editor')}}</button></div></section></template>
